    void load(){
        if(category.equals("Live Sports")){loadSports(false);return;}
        if(category.equals("Downloads")){++loadVersion;render();return;}
        if(playlistTab()){++loadVersion;loadPlaylist(false);return;}
        if(category.equals("Categories")){++loadVersion;render();loadGenres();return;}
        if(category.equals("Watch history")||category.equals("Search history")||category.equals("Watchlist")||category.equals("Continue")||category.equals("Collections")||category.equals("Plan to watch")){++loadVersion;catalog=localItems();render();return;}
        if(category.equals("Search")){if(!submittedQuery.isEmpty())onlineSearch();else {++loadVersion;render();}return;}
        if(!loadingMore)++renderVersion;lastRequested=SystemClock.elapsedRealtime();int token=++loadVersion;final boolean append=loadingMore;pageLoading=pageable();pageFailed=false;String section=category,live=liveBase(),q=query,key=tmdbKey();int offset=mangaOffset,page=browsePage,pid=providerId;int selectedGenre=genreId;String selectedGenreType=genreType;String providerMedia=providerType,region=prefs.getString("providerRegion","PH");
        status.setText("Updating "+section.toLowerCase(Locale.ROOT)+"…");
        io.execute(()->{try{JSONObject genreData=section.equals("Genre")?(genreName.startsWith("Anime")?ContentApi.animeData(key,selectedGenreType,page):ContentApi.genreData(key,selectedGenreType,selectedGenre,page)):section.equals("Provider")?ContentApi.providerPageData(key,providerMedia,pid,region,page):section.equals("Movies")||section.equals("Series")?ContentApi.browsePageData(key,section,page):null;List<Catalog.Item> rows=section.equals("Manga")?ContentApi.manga(q,offset):section.equals("Live")?ContentApi.live(live):genreData!=null?ContentApi.tmdbRows(genreData.getJSONArray("results"),section.equals("Genre")?selectedGenreType:section.equals("Provider")?providerMedia:section.equals("Series")?"tv":"movie",false):section.equals("Provider")?ContentApi.providerTitles(key,providerMedia,pid,region,page):ContentApi.browseMovies(key,section,page);
            ui.post(()->{if(isDestroyed()||token!=loadVersion)return;if(genreData!=null)genreHasMore=CatalogPaging.hasMore(page,genreData.optInt("total_pages",1));pageLoading=false;loadingMore=false;pageHasMore=genreData!=null&&CatalogPaging.hasMore(page,genreData.optInt("total_pages",1));if(append)mergeCatalog(rows);else catalog=rows;if(section.equals("Watchlist")||section.equals("Continue")||section.equals("Collections")){for(Map.Entry<String,?> entry:prefs.getAll().entrySet())if(entry.getKey().startsWith("saved:")&&entry.getValue() instanceof String)try{Catalog.Item savedItem=new Catalog.Item(new JSONObject((String)entry.getValue()));boolean found=false;for(Catalog.Item existing:catalog)if(existing.id.equals(savedItem.id))found=true;if(!found)catalog.add(savedItem);}catch(JSONException ignored){}}if(!section.equals("Live")&&!section.equals("Manga")){LinkedHashMap<String,Catalog.Item> saved=new LinkedHashMap<>();for(Catalog.Item item:browse)saved.put(item.id,item);for(Catalog.Item item:rows)saved.put(item.id,item);browse=new ArrayList<>(saved.values());}
                status.setText(section.equals("Manga")?"MangaDex · English chapters":section.equals("Live")?"Today's sports":"TMDB · "+rows.size()+" titles"+(pageable()?" · "+catalog.size()+" loaded":""));if(append)appendPage(rows);else render();});
        }catch(Exception e){ui.post(()->{if(isDestroyed()||token!=loadVersion)return;pageLoading=false;loadingMore=false;if(!append)pageHasMore=false;if(append){browsePage=Math.max(1,browsePage-1);pageFailed=true;updatePagingFooter();return;}status.setText(key.isEmpty()&&!section.equals("Live")&&!section.equals("Manga")?"Add your TMDB API key in Settings to browse movies and series":"Content service unavailable · showing previous results");render();});}});
    }
