    void submitSearch(){
        ((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);
        submittedQuery=query.trim();
        if(category.equals("Live Sports")){render();return;}
        if(playlistTab()){channelGroup="All";scroll.scrollTo(0,0);render();return;}
        ++surpriseVersion;++searchVersion;++loadVersion;resetPaging();category="Search";collection="";
        catalog=new ArrayList<>();scroll.scrollTo(0,0);if(!submittedQuery.isEmpty())history.search(submittedQuery);render();if(!submittedQuery.isEmpty())onlineSearch();
    }
    void mergeCatalog(List<Catalog.Item> rows){List<Catalog.Item> added=CatalogPaging.append(catalog,rows);rows.clear();rows.addAll(added);if(rows.isEmpty())pageHasMore=false;}
    void appendPage(List<Catalog.Item> rows){
        if(pagingFooter!=null){content.removeView(pagingFooter);pagingFooter=null;}
        if(sort.equals("Featured")){grid(rows,renderVersion);updatePagingFooter();}
        else {int y=scroll.getScrollY();View focus=getCurrentFocus();String label=focus==null?null:String.valueOf(focus.getContentDescription());render();scroll.post(()->{scroll.scrollTo(0,y);restoreFocus(content,label);});}
        scroll.post(this::maybeLoadNextPage);
    }
    void restoreFocus(View view,String label){if(label==null||label.equals("null"))return;if(label.contentEquals(view.getContentDescription()==null?"":view.getContentDescription())){view.requestFocus();return;}if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)restoreFocus(((ViewGroup)view).getChildAt(i),label);}
    void updatePagingFooter(){
        if(!pageable())return;
        if(pagingFooter!=null)content.removeView(pagingFooter);pagingFooter=column();pagingFooter.setPadding(0,dp(12),0,dp(14));
        if(pageFailed){pagingFooter.addView(text("Could not load more. Your current results are kept.",14,MUTED));pagingFooter.addView(button("Retry loading more",()->{pageFailed=false;maybeLoadNextPage();}));}
        else pagingFooter.addView(text(pageLoading?"Loading more…":pageHasMore?"More titles load as you scroll":"You have reached the end",13,MUTED));
        content.addView(pagingFooter);
    }
    void maybeLoadNextPage(){
        if(!foreground||!ready||detailsOpen||!pageable()||pageLoading||!pageHasMore||pageFailed||catalog.isEmpty()||content.getHeight()==0)return;
        if(scroll.getScrollY()+scroll.getHeight()+dp(240)<content.getHeight())return;
        loadingMore=true;pageLoading=true;if(category.equals("Search")){searchPage++;onlineSearch();}else{browsePage++;load();}updatePagingFooter();
    }
    void loadPlaylist(boolean force){
        if(!playlistTab())return;String section=category;boolean live=section.equals("LiveTV");
        PlaylistStore.Snapshot existing=playlists.get(section);
        if(!force&&existing!=null&&(!live||System.currentTimeMillis()-existing.updated<M3uPlaylist.LIVE_TTL)){scheduleLiveRefresh();return;}
        if(!playlistLoading.add(section))return;playlistErrors.remove(section);render();
        io.execute(()->{
            PlaylistStore.Snapshot cached=existing;
            if(cached==null)try{cached=PlaylistStore.cached(getApplicationContext(),live);}catch(IOException ignored){}
            final PlaylistStore.Snapshot fallback=cached;
            if(cached!=null)ui.post(()->{if(isDestroyed())return;playlists.put(section,fallback);if(category.equals(section))render();});
            try{
                PlaylistStore.Snapshot result=!force&&cached!=null&&(!live||System.currentTimeMillis()-cached.updated<M3uPlaylist.LIVE_TTL)?cached:PlaylistStore.fetch(getApplicationContext(),live);
                ui.post(()->{if(isDestroyed())return;playlistLoading.remove(section);playlists.put(section,result);playlistErrors.remove(section);if(category.equals(section)){renderPlaylistPreservingPosition();scheduleLiveRefresh();}});
            }catch(Exception error){ui.post(()->{if(isDestroyed())return;playlistLoading.remove(section);playlistErrors.put(section,"Refresh unavailable. "+(fallback==null?"Check your connection and try again.":"Showing the last saved channels."));if(category.equals(section)){renderPlaylistPreservingPosition();scheduleLiveRefresh();}});}
        });
    }
    void scheduleLiveRefresh(){
        ui.removeCallbacks(liveRefresh);if(!foreground||!category.equals("LiveTV"))return;
        PlaylistStore.Snapshot list=playlists.get("LiveTV");long delay=list==null?60_000:Math.max(60_000,M3uPlaylist.LIVE_TTL-(System.currentTimeMillis()-list.updated));ui.postDelayed(liveRefresh,delay);
    }
    void renderPlaylistPreservingPosition(){int y=scroll.getScrollY();View focus=getCurrentFocus();String label=focus==null?null:String.valueOf(focus.getContentDescription());render();scroll.post(()->{scroll.scrollTo(0,y);restoreFocus(content,label);});}
