    static final class GenreImageTask {final String type;final int id,token;final ImageView image;GenreImageTask(String type,int id,ImageView image,int token){this.type=type;this.id=id;this.image=image;this.token=token;}}
    void genrePicture(String type,int id,ImageView image,int token){
        String key=type+id,url=genreArtwork.get(key);
        if(url==null)for(Catalog.Item item:browse){if(!ContentApi.media(item).equals(type))continue;JSONArray genres=item.raw.optJSONArray("genreIds");if(genres==null)continue;for(int i=0;i<genres.length();i++)if(genres.optInt(i)==id){url=item.raw.optString("backdrop");if(url.isEmpty())url=item.poster;if(!url.isEmpty())break;}if(url!=null&&!url.isEmpty())break;}
        if(url!=null&&!url.isEmpty()){genreArtwork.put(key,url);picture(url,image,token);return;}
        pendingGenreArtwork.put(image,new GenreImageTask(type,id,image,token));image.post(()->ui.post(visiblePictures));
    }
    void loadVisibleGenreArtwork(){
        Rect visible=new Rect();Iterator<Map.Entry<ImageView,GenreImageTask>> iterator=pendingGenreArtwork.entrySet().iterator();List<GenreImageTask> tasks=new ArrayList<>();while(iterator.hasNext()){Map.Entry<ImageView,GenreImageTask> entry=iterator.next();GenreImageTask task=entry.getValue();if(task.token!=renderVersion){iterator.remove();continue;}if(entry.getKey().isShown()&&entry.getKey().getGlobalVisibleRect(visible)){tasks.add(task);iterator.remove();}}
        for(GenreImageTask task:tasks){String key=task.type+task.id;String cached=genreArtwork.get(key);if(cached!=null){picture(cached,task.image,task.token);continue;}if(!genreArtworkLoading.add(key)){pendingGenreArtwork.put(task.image,task);continue;}String apiKey=tmdbKey();io.execute(()->{String url="";try{List<Catalog.Item> examples=ContentApi.tmdbRows(ContentApi.genreData(apiKey,task.type,task.id,1).getJSONArray("results"),task.type,false);for(Catalog.Item item:examples){url=item.raw.optString("backdrop");if(url.isEmpty())url=item.poster;if(!url.isEmpty())break;}}catch(Exception ignored){}final String art=url;ui.post(()->{genreArtworkLoading.remove(key);if(isDestroyed())return;if(!art.isEmpty()){genreArtwork.put(key,art);if(task.token==renderVersion&&category.equals("Categories"))picture(art,task.image,task.token);ui.post(visiblePictures);}});});}
    }

    @Override protected void onDestroy(){++searchVersion;++loadVersion;++renderVersion;ui.removeCallbacksAndMessages(null);io.shutdownNow();imageIo.shutdownNow();pendingPictures.clear();pictureViews.clear();pictures.evictAll();super.onDestroy();}
